#!/usr/bin/env python3
"""Write already-completed v318 evidence. Never runs solvers or registers evals."""
from pathlib import Path
import base64,hashlib,json,zlib
ROOT=Path(__file__).resolve().parents[2]
EXPECTED='24de5a028ff3fcb97d1c1b6afbc1f9b3255865644a22057fb13243d15b99999d'
DATA=''
POST='''### 判定

不採用。現行v315を維持する。in100は親比59手増、固定参照相対−0.301163ポイント、31勝27分42敗だった。補助100件は68手減、41勝23分36敗だが、事前のin合計非悪化と相対改善を満たさない。平均195手以下も未達である。絶対値と各入力は[評価要約](../../adhoc/v318/evaluation_summary.json)と[対比較CSV](../../adhoc/v318/paired_scores.csv)へ保存する。

### 同値性と実行前の修正

保存100解の42,355候補で、3世代の履歴集計127,065件、32特徴8,132,160要素、選択3,600回を比較した。候補、順位、優先値、束候補、特徴と乱数がビット単位で一致した。人工履歴65,536条件と固定時計の8対でも一致を確認した。固定時計の16本はLOCALと非LOCAL各4入力で、すべて完走した。

最初の検査は、親自身で異なる演算式や古い世代と更新後の特徴を比較する誤りがあり、同じ世代の親子の実値を比較する形へ修正した。その後、実際の親子の優先値と特徴19だけに約1ULPの差が出た。命令列を照合し、親の乗算後の丸めが新版では積和へ縮約されていたため、refresh_regular_scoreの乗算をvolatile doubleへ保存して親の丸め境界を保持した。誤差許容を緩めず、通常評価の前に再固定して両版の機構検査をやり直した。旧検査、旧ソース、比較と理由は評価一式のresults/repairsへ残す。これは当初の同値性条件を満たす機構修正で、スコアを見ての戦略変更ではない。

### 計算費用と完成版

固定仕事量の局所検査では、索引の構築とソートを含む候補生成が31.50%、NN候補選択が59.44%短時間になった。各入力の測定順を交代したが、保存局面の限定的な分布であり、solver全体の速度比ではない。

完成版のinでは候補管理時間が平均11.34ms減り、LNS試行数が1.75%増えた。全面再構築は17.50ms減った一方、履歴のみと束候補の更新は合計6.17ms増えた。索引維持費と実際に訪れる局面が変わるため、これらを一回当たりの独立な因果効果としない。補助では候補管理が12.80ms減り、LNS試行数が4.20%増えた。

### 条件と限界

GCC14.2、C++23、LOCALなし、親の1.9秒予算を保持し、主探索約1.850777秒、終了期限1.880秒、2並列で比較した。各ケースの両版を同じCPUで続け、AB/BAを交代した。通常測定は各入力各版1回で、ウォームアップを除く。補助はvalidation1全500件ではなく、内容SHA256順でinと非重複の固定100件であり、新規未見集合ではない。参照は以前の評価一式にあるv800を含む保存最小値で、公式順位の相対値とは区別する。

全400出力が独立Python/C++再生で合法、全帰巣、T/E/S一致、既存診断エラー0だった。外部時間最大1.889085秒で全件1.9秒以内。公式Rust採点バイナリは実行していない。LOCAL/非LOCALの完全前処理でNN、再挿入、LNSの探索本体、育成の不変を確認した。追加学習、重み変更、時計変更はない。

原方向NN列のハッシュは200入力で一致し、保持候補の由来と手数はin95件、補助93件で一致した。追加列の全操作の一致は確認していない。0005を除く99件は69手増だった。in平均差の入力bootstrap95%区間は[-0.29,+1.45]手、補助は[-1.67,+0.29]手で、再実行時の時間変動は測っていない。安定した劣化とは断定しないが、今回の採用条件は未充足とする。

### 保存と次の前提

完全な単一CPP、復元入口、対比較CSVと要約、実験ノートをmainへ直接記録する。新版SHA256は24de5a028ff3fcb97d1c1b6afbc1f9b3255865644a22057fb13243d15b99999d。全出力、入力、診断、完全前処理、修正履歴と再現用入口は会話添付AHC072_v318_evaluation_bundle.zipへ保存する。Actionsは同じ非公開リポジトリの取得と記録にだけ使い、solverと学習は動かさない。一時workflowは完了後に削除する。新しいブランチ、eval viewerへの登録、共有評価ログの更新、通常評価後のsolver改変と再評価は行わない。

次の前提: 同値な履歴計算の削減自体は成立したが、全体では索引維持費があり、今回のinの完成手数は減らなかった。局所の倍率を完成版の改善量として扱わない。再開条件: 別環境での同じ凍結ソースの比較、または索引維持費を切り分ける別の具体的仮説に対する新しい明示指示。
'''
assert hashlib.sha256((ROOT/'src/bin/v318_bit_parallel_history.cpp').read_bytes()).hexdigest()==EXPECTED
for name,item in json.loads(zlib.decompress(base64.b64decode(DATA))).items():
    b=item['content'].encode();assert hashlib.sha256(b).hexdigest()==item['sha256'],name
    p=ROOT/name;p.parent.mkdir(parents=True,exist_ok=True)
    if p.exists():assert p.read_bytes()==b,'existing evidence differs: '+name
    else:p.write_bytes(b)
p=ROOT/'notes/experiments/v318.md';text=p.read_text()
if '\n## 実験後\n' not in text:p.write_text(text+'\n## 実験後\n\n'+POST)
else:assert POST in text,'post-experiment note differs'
p=ROOT/'notes/backlog.md';text=p.read_text()
needle='- **[B-106]'
lines=text.splitlines();found=[(i,line) for i,line in enumerate(lines) if line.startswith(needle)]
assert len(found)==1,'B-106 location is ambiguous'
i,line=found[0]
if 'v318検証済み' not in line:
    lines.pop(i);text='\n'.join(lines)+'\n'
    entry=line+' **v318検証済み** → [v318](experiments/v318.md) 不採用。現行v315に対し、64時刻のビット並列集計と世代内共有を実装。保存100列で候補と32特徴をビット一致で確認し、固定時計8対も一致した。局所の候補生成31.50%、NN選択59.44%短縮に対し、完成版in100は59手増、固定相対−0.301163ポイント。補助100件は68手減。全400出力合法かつ全帰巣、最大1.889085秒。通常評価前に丸め境界の機構修正を行い、得点を見ての改変はない。再開条件: 新しい明示指示による別環境比較または索引維持費の切り分け。\n'
    heading='## 決着済み\n';assert text.count(heading)==1
    text=text.replace(heading,heading+'\n'+entry,1);p.write_text(text)
print('v318 exact source/evidence/experiment note/backlog recorded; no solver executed')
